void CreateBufferResource(PP_Instance instance, uint32_t size, HostResource* result_resource, ppapi::proxy::SerializedHandle* result_shm_handle) {
    // Check permissions and resource creation validity
    if (!CheckPermission(instance)) {
        return;
    }

    // Allocate shared memory for the buffer
    void* buffer_memory = AllocateSharedMemory(size);
    if (!buffer_memory) {
        return;
    }

    // Platform-specific logic for retrieving the shared memory handle
    int fd = -1;
#if defined(OS_POSIX)
    fd = GetSharedMemoryFileDescriptor(buffer_memory);
#elif defined(OS_WIN)
    HANDLE handle = GetSharedMemoryHandle(buffer_memory);
    fd = _open_osfhandle((intptr_t)handle, 0);
#endif

    if (fd == -1) {
        FreeSharedMemory(buffer_memory);
        return;
    }

    // Create the HostResource for the buffer
    HostResource resource = CreateHostResource(instance, buffer_memory, size);
    if (!IsResourceValid(resource)) {
        FreeSharedMemory(buffer_memory);
        close(fd);
        return;
    }

    // Store the result in the output parameters
    *result_resource = resource;
    *result_shm_handle = SerializeHandle(fd);

    // Release the local reference to the shared memory
    FreeSharedMemory(buffer_memory);
}
